import{D as e}from"./index-BbvXgB4H.js";var t=`docs/references/hsk/sources/hsk3.pdf`,n=(e,n)=>`${t}#printed-pages=${e}&pdf-pages=${n}`,r=n(`124-132`,`136-144`),i=t=>({image:e(`/assets/group3/lesson-hsk3-l14-${t}-v1.webp`),imageSrcSet:`${e(`/assets/group3/lesson-hsk3-l14-${t}-720w-v1.webp`)} 720w, ${e(`/assets/group3/lesson-hsk3-l14-${t}-v1.webp`)} 1400w`}),a=(e,t)=>({...t,reading:t.pinyin,sourceRef:e}),o=(e,t,n)=>({zh:e,th:t,focus:n}),s=[[1,`词典`,`cídiǎn`,`n.`,`dictionary`,`พจนานุกรม`,125,137],[2,`最好`,`zuìhǎo`,`adv.`,`had better`,`ควรจะดีที่สุด`,125,137],[3,`节`,`jié`,`m.`,`class period; section`,`คาบ`,125,137],[4,`图书馆`,`túshūguǎn`,`n.`,`library`,`ห้องสมุด`,125,137],[5,`被`,`bèi`,`prep.`,`by; passive marker`,`ถูก (โครงสร้างกรรมวาจก)`,125,137],[6,`名人`,`míngrén`,`n.`,`celebrity; famous person`,`บุคคลมีชื่อเสียง`,125,137],[7,`故事`,`gùshi`,`n.`,`story`,`เรื่องราว`,125,137],[8,`然后`,`ránhòu`,`conj.`,`then`,`จากนั้น`,127,139],[9,`报纸`,`bàozhǐ`,`n.`,`newspaper`,`หนังสือพิมพ์`,127,139],[10,`忘记`,`wàngjì`,`v.`,`forget`,`ลืม`,127,139],[11,`电子书`,`diànzǐshū`,`n.`,`e-book`,`หนังสืออิเล็กทรอนิกส์`,127,139],[12,`女生`,`nǚshēng`,`n.`,`girl student`,`นักเรียนหญิง`,129,141],[13,`表演`,`biǎoyǎn`,`v.`,`perform`,`แสดง`,129,141],[14,`节目`,`jiémù`,`n.`,`program; performance`,`รายการ / การแสดง`,129,141],[15,`怎么办`,`zěnme bàn`,`phrase`,`what to do`,`ทำอย่างไรดี`,129,141],[16,`校长`,`xiàozhǎng`,`n.`,`principal`,`อธิการ / ผู้อำนวยการ`,129,141],[17,`面前`,`miànqián`,`n.`,`in front of; presence`,`ต่อหน้า`,129,141],[18,`有些`,`yǒuxiē`,`adv.`,`somewhat; rather`,`ค่อนข้าง`,129,141],[19,`相信`,`xiāngxìn`,`v.`,`believe`,`เชื่อมั่น`,129,141],[20,`新年`,`xīnnián`,`n.`,`New Year`,`ปีใหม่`,130,142],[21,`班级`,`bānjí`,`n.`,`class; grade`,`ชั้นเรียน`,130,142],[22,`跳`,`tiào`,`v.`,`jump; dance`,`กระโดด / เต้น`,130,142],[23,`留学生`,`liúxuéshēng`,`n.`,`international student`,`นักศึกษาต่างชาติ`,130,142],[24,`最后`,`zuìhòu`,`n./adv.`,`last; finally`,`สุดท้าย`,130,142],[25,`一块儿`,`yíkuàir`,`adv.`,`together`,`ด้วยกัน`,130,142],[26,`网站`,`wǎngzhàn`,`n.`,`website`,`เว็บไซต์`,130,142],[27,`视频`,`shìpín`,`n.`,`video`,`วิดีโอ`,130,142]].map(([e,t,r,i,a,o,s,c])=>({index:e,hanzi:t,pinyin:r,type:i,en:a,th:o,thAid:o,page:s,translationKind:`editorial-aid`,sourceRef:n(String(s),String(c))})),c=n(`125`,`137`),l=n(`127`,`139`),u=n(`128`,`140`),d={liWen:{hanzi:`李文`,pinyin:`Lǐ Wén`,nameTh:`หลี่เหวิน`,nameEn:`Li Wen`,...i(`library`),imageFocus:`34% center`},bai:{hanzi:`白家月`,pinyin:`Bái Jiāyuè`,nameTh:`ไป๋เจียเยว่`,nameEn:`Bai Jiayue`,...i(`library`),imageFocus:`66% center`},annie:{hanzi:`安妮`,pinyin:`Ānnī`,nameTh:`แอนนี่`,nameEn:`Annie`,...i(`campus`),imageFocus:`34% center`}},f=[{id:`h3l14-library`,number:`01`,glyph:`书`,title:`帮忙还书借书`,titleTh:`ช่วยคืนและยืมหนังสือ`,titleEn:`Returning and borrowing books`,place:`校园餐厅`,placeTh:`โรงอาหารมหาวิทยาลัย`,...i(`library`),source:`Text 1 · หน้าเล่ม 125 · PDF หน้า 137`,sourcePage:`125`,sourceRef:c,imageAlt:{zh:`校园餐厅谈借书场景`,th:`หลี่เหวินขอให้ไป๋เจียเยว่ช่วยคืนและยืมหนังสือ`,en:`Li Wen asking Bai Jiayue to return and borrow books`},context:`在校园餐厅，李文和白家月在聊天儿。`,contextTh:`ที่โรงอาหารมหาวิทยาลัย หลี่เหวินกับไป๋เจียเยว่คุยกัน`,contextEn:`In the campus cafeteria, Li Wen and Bai Jiayue chatted.`,characters:[{role:`A`,profile:`liWen`,noteZh:`请朋友帮忙还书的人`,noteTh:`ผู้ขอให้เพื่อนช่วยคืนหนังสือ`,noteEn:`The person asking a friend to return books`},{role:`B`,profile:`bai`,noteZh:`愿意帮忙的人`,noteTh:`ผู้ยินดีช่วย`,noteEn:`The friend willing to help`}],lines:[a(c,{role:`A`,speaker:`李文`,hanzi:`我借的这本词典最好今天还，但是我没时间去。`,pinyin:`Wǒ jiè de zhè běn cídiǎn zuìhǎo jīntiān huán, dànshì wǒ méi shíjiān qù.`,en:`I should return this dictionary today, but I do not have time to go.`,th:`พจนานุกรมที่ฉันยืมมาควรคืนวันนี้ แต่ฉันไม่มีเวลาไป`,visual:o(`词典最好今天还`,`ควรคืนพจนานุกรมวันนี้`,`34% center`)}),a(c,{role:`B`,speaker:`白家月`,hanzi:`下午我只有两节课，可以帮你去图书馆还书。`,pinyin:`Xiàwǔ wǒ zhǐ yǒu liǎng jié kè, kěyǐ bāng nǐ qù túshūguǎn huán shū.`,en:`I only have two classes this afternoon, so I can return it to the library for you.`,th:`บ่ายนี้ฉันมีเรียนแค่สองคาบ ช่วยเอาไปคืนห้องสมุดให้ได้`,visual:o(`帮你去还书`,`ช่วยเอาไปคืน`,`66% center`)}),a(c,{role:`A`,speaker:`李文`,hanzi:`那太谢谢了。你能再帮我借本书吗？`,pinyin:`Nà tài xièxie le. Nǐ néng zài bāng wǒ jiè běn shū ma?`,en:`Thank you so much. Could you also borrow a book for me?`,th:`ขอบคุณมาก ช่วยยืมหนังสือให้ฉันอีกเล่มได้ไหม?`,visual:o(`再帮我借本书`,`ช่วยยืมอีกเล่ม`,`36% center`)}),a(c,{role:`B`,speaker:`白家月`,hanzi:`行，你告诉我书名。`,pinyin:`Xíng, nǐ gàosu wǒ shūmíng.`,en:`Sure, tell me the title.`,th:`ได้ บอกชื่อหนังสือมา`,visual:o(`告诉我书名`,`บอกชื่อหนังสือ`,`64% center`)}),a(c,{role:`A`,speaker:`李文`,hanzi:`我把名字写在纸上吧。我去了好几次图书馆，这本书都被别人借走了。`,pinyin:`Wǒ bǎ míngzi xiě zài zhǐ shang ba. Wǒ qù le hǎo jǐ cì túshūguǎn, zhè běn shū dōu bèi biérén jiè zǒu le.`,en:`I will write the title on paper. I have gone several times, but this book was always checked out.`,th:`ฉันจะเขียนชื่อไว้บนกระดาษ ไปห้องสมุดหลายครั้งแล้ว แต่หนังสือนี้ถูกคนอื่นยืมไปทุกครั้ง`,visual:o(`被别人借走了`,`ถูกคนอื่นยืมไป`,`38% center`)}),a(c,{role:`B`,speaker:`白家月`,hanzi:`《名人的故事》？我有这本书。明天我借给你吧。`,pinyin:`Míngrén de Gùshi? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba.`,en:`Stories of Famous People? I have that book. I will lend it to you tomorrow.`,th:`เรื่องราวของบุคคลมีชื่อเสียงหรือ? ฉันมีเล่มนี้ พรุ่งนี้จะให้ยืม`,visual:o(`明天借给你`,`พรุ่งนี้ให้ยืม`,`62% center`)})],qte:{after:3,prompt:{zh:`李文为什么没借到那本书？`,th:`ทำไมหลี่เหวินยืมหนังสือเล่มนั้นไม่ได้?`,en:`Why could Li Wen not borrow the book?`},options:[{value:`被别人借走了`,zh:`被别人借走了`,pinyin:`bèi biérén jiè zǒu le`,th:`ถูกคนอื่นยืมไปแล้ว`},{value:`忘了书名`,zh:`忘了书名`,pinyin:`wàng le shūmíng`,th:`ลืมชื่อหนังสือ`},{value:`图书馆关门`,zh:`图书馆关门`,pinyin:`túshūguǎn guānmén`,th:`ห้องสมุดปิด`}],correct:`被别人借走了`,evidence:`李文：这本书都被别人借走了。`,evidenceTh:`หลี่เหวิน: หนังสือนี้ถูกคนอื่นยืมไปแล้ว`,sourceRef:c},builder:{prompt:{zh:`重组被动句`,th:`เรียงประโยคกรรมวาจก`,en:`Rebuild the passive sentence`},answer:[`这本书`,`被`,`别人`,`借走了`],tiles:[`借走了`,`别人`,`这本书`,`被`],gloss:{这本书:`หนังสือเล่มนี้`,被:`ถูก`,别人:`คนอื่น`,借走了:`ยืมไปแล้ว`},translationTh:`หนังสือเล่มนี้ถูกคนอื่นยืมไปแล้ว`,translationEn:`This book was checked out by someone else.`,evidence:`Text 1 · หน้าเล่ม 125`,sourceRef:c}},{id:`h3l14-campus`,number:`02`,glyph:`卡`,title:`校园卡不见了`,titleTh:`บัตรมหาวิทยาลัยหาย`,titleEn:`The missing campus card`,place:`校园`,placePy:`xiàoyuán`,placeTh:`มหาวิทยาลัย`,...i(`campus`),source:`Text 2 · หน้าเล่ม 127 · PDF หน้า 139`,sourcePage:`127`,sourceRef:l,imageAlt:{zh:`校园聊天场景`,th:`ไป๋เจียเยว่หาบัตรมหาวิทยาลัย`,en:`Bai Jiayue looking for her campus card`},context:`在校园里，白家月和安妮在聊天儿。`,contextTh:`ในมหาวิทยาลัย ไป๋เจียเยว่กับแอนนี่คุยกัน`,contextEn:`On campus, Bai Jiayue and Annie chatted.`,characters:[{role:`A`,profile:`annie`,noteZh:`想去图书馆看报纸的人`,noteTh:`ผู้ที่อยากไปอ่านหนังสือพิมพ์`,noteEn:`The person going to read newspapers`},{role:`B`,profile:`bai`,noteZh:`找不到校园卡的人`,noteTh:`ผู้ที่หาบัตรมหาวิทยาลัยไม่เจอ`,noteEn:`The person missing a campus card`}],lines:[a(l,{role:`A`,speaker:`安妮`,hanzi:`今天下课早，你一会儿做什么？`,pinyin:`Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?`,en:`Class ends early today. What will you do later?`,th:`วันนี้เลิกเรียนเร็ว เดี๋ยวเธอจะทำอะไร?`,visual:o(`一会儿做什么`,`เดี๋ยวทำอะไร`,`34% center`)}),a(l,{role:`B`,speaker:`白家月`,hanzi:`我今天忙得很，要先去图书馆借书，然后去游泳。`,pinyin:`Wǒ jīntiān máng de hěn, yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.`,en:`I am very busy today. First I must borrow books, then go swimming.`,th:`วันนี้ฉันยุ่งมาก ต้องไปยืมหนังสือก่อน แล้วค่อยไปว่ายน้ำ`,visual:o(`先借书然后游泳`,`ยืมหนังสือก่อนแล้วว่ายน้ำ`,`66% center`)}),a(l,{role:`A`,speaker:`安妮`,hanzi:`咱们一起走吧，我想去图书馆看看中文报纸。`,pinyin:`Zánmen yìqǐ zǒu ba, wǒ xiǎng qù túshūguǎn kànkan Zhōngwén bàozhǐ.`,en:`Let us go together. I want to read Chinese newspapers in the library.`,th:`ไปด้วยกันเถอะ ฉันอยากไปอ่านหนังสือพิมพ์จีนที่ห้องสมุด`,visual:o(`看看中文报纸`,`อ่านหนังสือพิมพ์จีน`,`36% center`)}),a(l,{role:`B`,speaker:`白家月`,hanzi:`等等，我的校园卡不见了，没有卡进不去图书馆。`,pinyin:`Děngdeng, wǒ de xiàoyuánkǎ bú jiàn le, méiyǒu kǎ jìn bu qù túshūguǎn.`,en:`Wait, my campus card is gone. Without it I cannot enter the library.`,th:`เดี๋ยวก่อน บัตรมหาวิทยาลัยฉันหาย ไม่มีบัตรก็เข้าห้องสมุดไม่ได้`,visual:o(`校园卡不见了`,`บัตรมหาวิทยาลัยหาย`,`64% center`)}),a(l,{role:`A`,speaker:`安妮`,hanzi:`你想想上一次用是什么时候？`,pinyin:`Nǐ xiǎngxiang shàng yí cì yòng shì shénme shíhou?`,en:`Think about when you last used it.`,th:`ลองคิดดูว่าครั้งล่าสุดใช้เมื่อไร`,visual:o(`上一次用`,`ใช้ครั้งล่าสุด`,`38% center`)}),a(l,{role:`B`,speaker:`白家月`,hanzi:`我忘记了，可能被我放在家里了。`,pinyin:`Wǒ wàngjì le, kěnéng bèi wǒ fàng zài jiāli le.`,en:`I forgot. It may have been left at home by me.`,th:`ฉันลืมแล้ว อาจถูกฉันวางไว้ที่บ้าน`,visual:o(`可能放在家里`,`อาจวางไว้ที่บ้าน`,`62% center`)}),a(l,{role:`A`,speaker:`安妮`,hanzi:`进不去图书馆也没关系，上网看看有没有电子书。`,pinyin:`Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū.`,en:`It is fine if you cannot enter. Check online for an e-book.`,th:`เข้าห้องสมุดไม่ได้ก็ไม่เป็นไร ลองดูออนไลน์ว่ามีอีบุ๊กไหม`,visual:o(`上网看电子书`,`ดูอีบุ๊กออนไลน์`,`40% center`)}),a(l,{role:`B`,speaker:`白家月`,hanzi:`不行，我必须去，我还得帮李文还书呢。`,pinyin:`Bù xíng, wǒ bìxū qù, wǒ hái děi bāng Lǐ Wén huán shū ne.`,en:`No, I must go because I still have to return Li Wen's book.`,th:`ไม่ได้ ฉันต้องไป ยังต้องช่วยหลี่เหวินคืนหนังสือด้วย`,visual:o(`必须去还书`,`ต้องไปคืนหนังสือ`,`60% center`)})],qte:{after:3,prompt:{zh:`白家月为什么进不去图书馆？`,th:`ทำไมไป๋เจียเยว่เข้าห้องสมุดไม่ได้?`,en:`Why could Bai Jiayue not enter the library?`},options:[{value:`校园卡不见了`,zh:`校园卡不见了`,pinyin:`xiàoyuánkǎ bú jiàn le`,th:`บัตรมหาวิทยาลัยหาย`},{value:`忘了书名`,zh:`忘了书名`,pinyin:`wàng le shūmíng`,th:`ลืมชื่อหนังสือ`},{value:`下课太晚`,zh:`下课太晚`,pinyin:`xiàkè tài wǎn`,th:`เลิกเรียนสายเกินไป`}],correct:`校园卡不见了`,evidence:`白家月：我的校园卡不见了。`,evidenceTh:`ไป๋เจียเยว่: บัตรมหาวิทยาลัยของฉันหาย`,sourceRef:l},builder:{prompt:{zh:`重组承接复句`,th:`เรียงประโยคลำดับเหตุการณ์`,en:`Rebuild the successive sentence`},answer:[`要先去`,`图书馆借书`,`然后`,`去游泳`],tiles:[`去游泳`,`然后`,`图书馆借书`,`要先去`],gloss:{要先去:`ต้องไปก่อน`,图书馆借书:`ยืมหนังสือที่ห้องสมุด`,然后:`จากนั้น`,去游泳:`ไปว่ายน้ำ`},translationTh:`ต้องไปยืมหนังสือที่ห้องสมุดก่อน แล้วค่อยไปว่ายน้ำ`,translationEn:`First go borrow books, then go swimming.`,evidence:`Text 2 · หน้าเล่ม 127`,sourceRef:l}},{id:`h3l14-performance`,number:`03`,glyph:`演`,title:`准备晚会节目`,titleTh:`เตรียมการแสดงงานเลี้ยง`,titleEn:`Preparing a party performance`,place:`校园餐厅`,placeTh:`โรงอาหารมหาวิทยาลัย`,...i(`performance`),source:`Text 3 · หน้าเล่ม 128 · PDF หน้า 140`,sourcePage:`128`,sourceRef:u,imageAlt:{zh:`校园餐厅晚会讨论场景`,th:`คุยเรื่องการแสดงงานเลี้ยงโรงเรียน`,en:`Discussing a school party performance`},context:`在校园餐厅，李文和白家月边吃边聊。`,contextTh:`ที่โรงอาหารมหาวิทยาลัย หลี่เหวินกับไป๋เจียเยว่กินไปคุยไป`,contextEn:`In the campus cafeteria, Li Wen and Bai Jiayue chatted while eating.`,characters:[{role:`A`,profile:`liWen`,noteZh:`想唱中文歌但感到紧张的人`,noteTh:`ผู้ที่อยากร้องเพลงจีนแต่กังวล`,noteEn:`The nervous singer`},{role:`B`,profile:`bai`,noteZh:`鼓励朋友相信自己的人`,noteTh:`ผู้ให้กำลังใจเพื่อน`,noteEn:`The encouraging friend`}],lines:[a(u,{role:`A`,speaker:`李文`,hanzi:`下周学校有晚会，你知道吗？`,pinyin:`Xià zhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?`,en:`There is a school party next week. Did you know?`,th:`สัปดาห์หน้าโรงเรียนมีงานเลี้ยง เธอรู้ไหม?`,visual:o(`学校有晚会`,`โรงเรียนมีงานเลี้ยง`,`34% center`)}),a(u,{role:`B`,speaker:`白家月`,hanzi:`知道，我和几个女生要表演一个节目。你也参加吗？`,pinyin:`Zhīdào, wǒ hé jǐ ge nǚshēng yào biǎoyǎn yí ge jiémù. Nǐ yě cānjiā ma?`,en:`Yes. Several girls and I will perform. Are you joining too?`,th:`รู้ ฉันกับนักเรียนหญิงหลายคนจะแสดงหนึ่งรายการ เธอเข้าร่วมด้วยไหม?`,visual:o(`表演一个节目`,`แสดงหนึ่งรายการ`,`66% center`)}),a(u,{role:`A`,speaker:`李文`,hanzi:`我想唱中文歌，但是还没找到人一起表演，不知道怎么办。`,pinyin:`Wǒ xiǎng chàng Zhōngwén gē, dànshì hái méi zhǎodào rén yìqǐ biǎoyǎn, bù zhīdào zěnme bàn.`,en:`I want to sing a Chinese song, but I have not found anyone to perform with and do not know what to do.`,th:`ฉันอยากร้องเพลงจีน แต่ยังหาคนแสดงด้วยไม่ได้ ไม่รู้จะทำอย่างไร`,visual:o(`不知道怎么办`,`ไม่รู้ทำอย่างไรดี`,`36% center`)}),a(u,{role:`B`,speaker:`白家月`,hanzi:`找不到人，你就一个人唱吧。`,pinyin:`Zhǎo bu dào rén, nǐ jiù yí ge rén chàng ba.`,en:`If you cannot find anyone, sing by yourself.`,th:`ถ้าหาคนไม่ได้ เธอก็ร้องคนเดียวสิ`,visual:o(`一个人唱吧`,`ร้องคนเดียวเถอะ`,`64% center`)}),a(u,{role:`A`,speaker:`李文`,hanzi:`一想到要在校长、老师和那么多同学面前表演，我就有些紧张。`,pinyin:`Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng.`,en:`Whenever I think about performing before the principal, teachers, and so many students, I get nervous.`,th:`พอคิดว่าต้องแสดงต่อหน้าผู้อำนวยการ ครู และนักเรียนมากมาย ฉันก็ค่อนข้างกังวล`,visual:o(`我就有些紧张`,`ฉันค่อนข้างกังวล`,`38% center`)}),a(u,{role:`B`,speaker:`白家月`,hanzi:`紧张什么啊，我们都喜欢听你唱歌，你要相信自己。`,pinyin:`Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.`,en:`What is there to be nervous about? We all like hearing you sing. Believe in yourself.`,th:`จะกังวลอะไรล่ะ พวกเราชอบฟังเธอร้องเพลง เธอต้องเชื่อมั่นในตัวเอง`,visual:o(`相信自己`,`เชื่อมั่นในตัวเอง`,`62% center`)})],qte:{after:3,prompt:{zh:`李文为什么紧张？`,th:`ทำไมหลี่เหวินจึงกังวล?`,en:`Why was Li Wen nervous?`},options:[{value:`要在很多人面前表演`,zh:`要在很多人面前表演`,pinyin:`yào zài hěn duō rén miànqián biǎoyǎn`,th:`ต้องแสดงต่อหน้าคนมากมาย`},{value:`不会唱中文歌`,zh:`不会唱中文歌`,pinyin:`bú huì chàng Zhōngwén gē`,th:`ร้องเพลงจีนไม่เป็น`},{value:`忘了节目时间`,zh:`忘了节目时间`,pinyin:`wàng le jiémù shíjiān`,th:`ลืมเวลาแสดง`}],correct:`要在很多人面前表演`,evidence:`李文：一想到要在校长、老师和那么多同学面前表演，我就有些紧张。`,evidenceTh:`หลี่เหวิน: พอคิดว่าต้องแสดงต่อหน้าคนมากมาย ฉันก็กังวล`,sourceRef:u},builder:{prompt:{zh:`重组安慰句`,th:`เรียงประโยคให้กำลังใจ`,en:`Rebuild the reassurance`},answer:[`紧张什么啊`,`你要`,`相信`,`自己`],tiles:[`自己`,`相信`,`紧张什么啊`,`你要`],gloss:{紧张什么啊:`จะกังวลอะไร`,你要:`เธอต้อง`,相信:`เชื่อมั่น`,自己:`ตัวเอง`},translationTh:`จะกังวลอะไร เธอต้องเชื่อมั่นในตัวเอง`,translationEn:`What is there to be nervous about? Believe in yourself.`,evidence:`Text 3 · หน้าเล่ม 128`,sourceRef:u}}],p={id:`hsk3-l14`,slug:`lesson-14`,level:`hsk3`,number:14,featured:!1,sourceRef:r,source:{title:`新HSK教程 3 · New HSK Course 3`,lesson:`Lesson 14 · 这本书被别人借走了`,printedPages:`124–132`,pdfPages:`136–144`,file:`hsk3.pdf`,sourceRef:r},title:{zh:`这本书被别人借走了`,pinyin:`Zhè běn shū bèi biérén jiè zǒu le`,en:`This book is checked out`,thAid:`หนังสือเล่มนี้ถูกคนอื่นยืมไปแล้ว`},summary:{zh:`谈图书馆、校园安排和晚会表演，学习被动句和鼓励表达。`,en:`Discuss libraries, campus plans, and performances while learning passives and encouragement.`,thAid:`พูดคุยเรื่องห้องสมุด กิจกรรมมหาวิทยาลัย และการแสดง พร้อมเรียนกรรมวาจกกับถ้อยคำให้กำลังใจ`},translationPolicy:{kind:`editorial-aid`,labelTh:`คำแปลไทยเพื่อช่วยเรียน เรียบเรียงจากต้นฉบับ`},objectives:[{zh:`能听懂并介绍校园活动。`,en:`Be able to understand and introduce campus activities.`,thAid:`ฟังเข้าใจและแนะนำกิจกรรมในมหาวิทยาลัย`,sourceRef:n(`124`,`136`)},{zh:`能听懂并表达对他人的鼓励。`,en:`Be able to understand and express encouragement to others.`,thAid:`ฟังเข้าใจและกล่าวให้กำลังใจผู้อื่น`,sourceRef:n(`124`,`136`)},{zh:`掌握被动句（1）的用法，能表达被动意义。`,en:`Master passive sentences (1) to express passive meaning.`,thAid:`ใช้ประโยคกรรมวาจกแบบที่ 1 เพื่อสื่อความหมายเชิงถูกกระทำ`,sourceRef:n(`124`,`136`)}],contents:[{number:`00`,title:`目标与热身`,titleTh:`เป้าหมายและการเตรียมบท`,detail:`Objectives · Warm-Up`,pages:`124`,route:`/home/hsk3/lesson-14/preface/`,sourceRef:n(`124`,`136`)},{number:`01`,title:`帮忙还书借书`,titleTh:`ช่วยคืนและยืมหนังสือ`,detail:`Text 1 · New Words 1–7`,pages:`125–126`,scene:1,sourceRef:n(`125-126`,`137-138`)},{number:`02`,title:`校园卡不见了`,titleTh:`บัตรมหาวิทยาลัยหาย`,detail:`Text 2 · New Words 8–11`,pages:`126–128`,scene:2,sourceRef:n(`126-128`,`138-140`)},{number:`03`,title:`准备晚会节目`,titleTh:`เตรียมการแสดง`,detail:`Text 3 · New Words 12–19`,pages:`128–129`,scene:3,sourceRef:n(`128-129`,`140-141`)},{number:`04`,title:`新年晚会、练习与活动`,titleTh:`งานปีใหม่ แบบฝึก และกิจกรรม`,detail:`Text 4 · Exercises · Activity`,pages:`130–132`,sourceRef:n(`130-132`,`142-144`)}],vocabulary:s,grammarFocus:[{title:`被动句（1）`,titleEn:`Passive sentences (1)`,explanationZh:`结构“主语+被+宾语+动词+其他成分”突出主语受到动作影响；“被”后的宾语可省略。`,explanationEn:`Subject + 被 + agent + verb + other elements highlights how the subject is affected; the agent may be omitted.`,thAid:`ประธาน + 被 + ผู้กระทำ + กริยา + ส่วนอื่น เน้นว่าประธานได้รับผลจากการกระทำ และละผู้กระทำได้`,examples:[`这本书被别人借走了。`,`水果可能被弟弟吃了。`],sourceRef:n(`126`,`138`)},{title:`承接复句“先……，再/然后……”`,titleEn:`Successive complex sentence`,explanationZh:`两个分句表示动作发生的先后顺序。`,explanationEn:`The clauses present actions in chronological order.`,thAid:`อนุประโยคสองส่วนบอกลำดับก่อนหลังของการกระทำ`,examples:[`我要先去图书馆借书，然后去游泳。`,`你先买门票，再来找我。`],sourceRef:n(`127`,`139`)},{title:`固定格式“×什么（啊）”`,titleEn:`Reassuring pattern ×什么（啊）`,explanationZh:`用于否定对方的担忧或疑问，带有反驳或安慰语气。`,explanationEn:`This pattern dismisses a concern or doubt with a refuting or reassuring tone.`,thAid:`ใช้ปฏิเสธความกังวลหรือข้อสงสัยของอีกฝ่าย โดยมีน้ำเสียงโต้แย้งหรือปลอบใจ`,examples:[`紧张什么啊，你要相信自己。`,`急什么啊，马上就到了。`],sourceRef:n(`129`,`141`)}],characters:d,scenes:f};export{p as LESSON_HSK3_L14};